import { CloseDialog, renderRightSidebar, drawTagsIntoTables, filterDataByHeaderType, inputObserver, pageNumbers, fillBtnPagination, calculateLine, searchUniversalSingle, currentDateTime, sleep } from "../../../tools.js";
